    /// <summary>
    /// Coc for insert
    /// </summary>
    public void insert()
    {
        METWMSOrderTrans    metWMSOrderTrans;
        next insert();

        metWMSOrderTrans    =   this.metWMSOrderTrans();
        this.metPackMETWMSOrderTrans(metWMSOrderTrans);
        this.SysExtensionSerializerMap::postInsert();
    }

/// <summary>
/// Coc for update
/// </summary>
public void update()
{
    METWMSOrderTrans    metWMSOrderTrans;
    next update();
    
    metWMSOrderTrans    =   this.metWMSOrderTrans();
    if (!METWMSOrderTrans.WMSOrderTrans)
    {
        this.metPackMETWMSOrderTrans(metWMSOrderTrans);
    }
    this.SysExtensionSerializerMap::postUpdate();
}

/// <summary>
/// Find corresponding METWMSOrderTrans record
/// </summary>
/// <returns>METWMSOrderTrans record</returns>
public METWMSOrderTrans metWMSOrderTrans()
{
    return this.SysExtensionSerializerMap::getExtensionTable(tableNum(METWMSOrderTrans));
}

    /// <summary>
    /// pack the METWMSOrderTrans record fields
    /// </summary>
    /// <param name = "_metWMSOrderTrans">Record buffer of METWMSOrderTrans to pack</param>
    public void metPackMETWMSOrderTrans(METWMSOrderTrans _metWMSOrderTrans)
    {
        SalesLine               salesLine;

        _metWMSOrderTrans.WMSOrderTrans = this.RecId;

        //update cases, weight and volume when it's for sales line
        salesLine = SalesLine::findInventTransId(this.inventTransId);
        if(salesLine.RecId)
        {
            _metWMSOrderTrans.Cases = EcoResProductUnitConverter::convertForReleasedProduct(
                                        salesLine.ItemId,
                                        salesLine.InventDimId,
                                        this.qty,
                                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(salesLine.SalesUnit),
                                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(METConstants::unitcase),
                                        NoYes::Yes,
                                        NoYes::No);
            _metWMSOrderTrans.Weight = salesLine.displayMETGrossWeight() * this.qty;
            _metWMSOrderTrans.volume = salesLine.displayMETUnitVolume() * this.qty;
        }

        this.SysExtensionSerializerMap::packExtensionTable(_metWMSOrderTrans);
    }
